# Donor CRM with Campaign and Appeal Tracking

I'll create a comprehensive donor management system with campaign and appeal tracking capabilities.

```python
import streamlit as st
from dataclasses import dataclass, field
from datetime import datetime, date
from typing import List, Optional, Dict
from enum import Enum
import pandas as pd
import json

class DonorType(Enum):
    INDIVIDUAL = "Individual"
    ORGANIZATION = "Organization"
    FOUNDATION = "Foundation"

class CampaignStatus(Enum):
    PLANNING = "Planning"
    ACTIVE = "Active"
    COMPLETED = "Completed"
    PAUSED = "Paused"

class AppealType(Enum):
    EMAIL = "Email"
    DIRECT_MAIL = "Direct Mail"
    PHONE = "Phone"
    EVENT = "Event"
    SOCIAL_MEDIA = "Social Media"
    ONLINE = "Online"

class DonationStatus(Enum):
    PLEDGED = "Pledged"
    RECEIVED = "Received"
    REFUNDED = "Refunded"

@dataclass
class Donor:
    id: str
    name: str
    donor_type: DonorType
    email: str
    phone: str
    address: str
    total_donated: float = 0.0
    first_donation_date: Optional[date] = None
    last_donation_date: Optional[date] = None
    donation_count: int = 0
    tags: List[str] = field(default_factory=list)
    notes: str = ""
    preferred_contact: str = "Email"

@dataclass
class Campaign:
    id: str
    name: str
    description: str
    start_date: date
    end_date: date
    goal_amount: float
    raised_amount: float = 0.0
    status: CampaignStatus = CampaignStatus.PLANNING
    appeals: List[str] = field(default_factory=list)
    notes: str = ""

@dataclass
class Appeal:
    id: str
    campaign_id: str
    name: str
    appeal_type: AppealType
    send_date: date
    target_segment: str
    message: str
    cost: float = 0.0
    responses: int = 0
    donations_generated: float = 0.0
    notes: str = ""

@dataclass
class Donation:
    id: str
    donor_id: str
    campaign_id: str
    appeal_id: Optional[str]
    amount: float
    donation_date: date
    status: DonationStatus
    payment_method: str
    notes: str = ""

class DonorCRM:
    def __init__(self):
        self.donors: Dict[str, Donor] = {}
        self.campaigns: Dict[str, Campaign] = {}
        self.appeals: Dict[str, Appeal] = {}
        self.donations: Dict[str, Donation] = {}

    def add_donor(self, donor: Donor):
        self.donors[donor.id] = donor

    def add_campaign(self, campaign: Campaign):
        self.campaigns[campaign.id] = campaign

    def add_appeal(self, appeal: Appeal):
        self.appeals[appeal.id] = appeal
        if appeal.campaign_id in self.campaigns:
            if appeal.id not in self.campaigns[appeal.campaign_id].appeals:
                self.campaigns[appeal.campaign_id].appeals.append(appeal.id)

    def add_donation(self, donation: Donation):
        self.donations[donation.id] = donation

        # Update donor statistics
        if donation.donor_id in self.donors:
            donor = self.donors[donation.donor_id]
            if donation.status == DonationStatus.RECEIVED:
                donor.total_donated += donation.amount
                donor.donation_count += 1
                donor.last_donation_date = donation.donation_date
                if donor.first_donation_date is None:
                    donor.first_donation_date = donation.donation_date

        # Update campaign raised amount
        if donation.campaign_id in self.campaigns and donation.status == DonationStatus.RECEIVED:
            self.campaigns[donation.campaign_id].raised_amount += donation.amount

        # Update appeal statistics
        if donation.appeal_id and donation.appeal_id in self.appeals:
            appeal = self.appeals[donation.appeal_id]
            appeal.responses += 1
            if donation.status == DonationStatus.RECEIVED:
                appeal.donations_generated += donation.amount

    def get_campaign_analytics(self, campaign_id: str) -> Dict:
        if campaign_id not in self.campaigns:
            return {}

        campaign = self.campaigns[campaign_id]
        campaign_donations = [d for d in self.donations.values() 
                            if d.campaign_id == campaign_id and d.status == DonationStatus.RECEIVED]

        total_donors = len(set(d.donor_id for d in campaign_donations))
        avg_donation = campaign.raised_amount / len(campaign_donations) if campaign_donations else 0
        progress = (campaign.raised_amount / campaign.goal_amount * 100) if campaign.goal_amount > 0 else 0

        return {
            "total_raised": campaign.raised_amount,
            "goal": campaign.goal_amount,
            "progress_percent": progress,
            "total_donations": len(campaign_donations),
            "unique_donors": total_donors,
            "average_donation": avg_donation,
            "appeals_count": len(campaign.appeals)
        }

    def get_appeal_analytics(self, appeal_id: str) -> Dict:
        if appeal_id not in self.appeals:
            return {}

        appeal = self.appeals[appeal_id]
        roi = ((appeal.donations_generated - appeal.cost) / appeal.cost * 100) if appeal.cost > 0 else 0
        conversion_rate = (appeal.responses / 100) * 100  # Placeholder - would need sends count

        return {
            "responses": appeal.responses,
            "donations_generated": appeal.donations_generated,
            "cost": appeal.cost,
            "roi_percent": roi,
            "avg_gift": appeal.donations_generated / appeal.responses if appeal.responses > 0 else 0
        }

    def get_donor_segments(self) -> Dict[str, List[Donor]]:
        segments = {
            "major_donors": [],
            "regular_donors": [],
            "lapsed_donors": [],
            "new_donors": []
        }

        today = date.today()

        for donor in self.donors.values():
            if donor.total_donated >= 10000:
                segments["major_donors"].append(donor)
            elif donor.donation_count >= 3:
                segments["regular_donors"].append(donor)
            elif donor.last_donation_date and (today - donor.last_donation_date).days > 365:
                segments["lapsed_donors"].append(donor)
            elif donor.donation_count == 1:
                segments["new_donors"].append(donor)

        return segments

def initialize_session_state():
    if 'crm' not in st.session_state:
        st.session_state.crm = DonorCRM()
    if 'donor_counter' not in st.session_state:
        st.session_state.donor_counter = 1
    if 'campaign_counter' not in st.session_state:
        st.session_state.campaign_counter = 1
    if 'appeal_counter' not in st.session_state:
        st.session_state.appeal_counter = 1
    if 'donation_counter' not in st.session_state:
        st.session_state.donation_counter = 1

def main():
    st.set_page_config(page_title="Donor CRM", page_icon="💝", layout="wide")
    initialize_session_state()

